WITH base AS (SELECT id, customer_id, store_id, order_date, status, channel, amount, discount, shipping_fee, ADD_MONTHS(order_date, 12) AS order_date_plus_months, COALESCE(channel, 'UNKNOWN') AS resolved_channel FROM orders WHERE order_date >= DATE '2023-06-23' AND channel IS NOT NULL) SELECT DATE_TRUNC('QUARTER', order_date) AS quarter_start, status, PERCENTILE_APPROX(discount, ARRAY(0.25, 0.5, 0.75)) AS discount_quartiles, SORT_ARRAY(COLLECT_SET(status)) AS status_list, MAX(shipping_fee) FILTER (WHERE status = 'CANCELLED') AS cancelled_max_shipping_fee, SORT_ARRAY(COLLECT_SET(channel)) AS channel_list, GROUPING(DATE_TRUNC('QUARTER', order_date)) AS grouping_id FROM base GROUP BY CUBE (DATE_TRUNC('QUARTER', order_date), status) HAVING cancelled_max_shipping_fee > 0 ORDER BY quarter_start DESC
